from packaging.specifiers import Specifier


def version_in_specifier(version: str, specifier: str) -> bool:
    """Check if a version is contained in a specifier. version: A version string to check against the specifier, e.g. '1.2.3' -> true for specifier '>=1.0'. specifier: A version specifier string (e.g., '>=1.0', '==1.2.3')."""
    try:
        spec = Specifier(specifier)
        return version in spec
    except Exception as e:
        raise ValueError(f"invalid specifier {specifier!r}: {str(e)}") from e
```

```python
from packaging.specifiers import SpecifierSet


def version_in_specifier_set(version: str, specifier_set: str) -> bool:
    """Check if a version is contained in a specifier set. version: A version string to check against the specifier set, e.g. '3.2' specifier_set: A string representation of a specifier set (e.g., '>=3.0,!=3.1') -> true if version satisfies all specifiers in the set."""
    try:
        spec_set = SpecifierSet(specifier_set)
        return version in spec_set
    except Exception as e:
        raise ValueError(f"invalid specifier set {specifier_set!r}: {e}") from e
