from packaging.utils import parse_wheel_filename as _parse_wheel_filename
from packaging.utils import InvalidWheelFilename
from packaging.version import Version
from packaging.tags import Tag
from packaging.utils import NormalizedName


def parse_wheel_filename(filename: str) -> dict[str, str | dict[str, str] | list[dict[str, str]] | None]:
    """Parse a wheel filename into its components. filename: The name of the wheel file, e.g. 'foo-1.0-py3-none-any.whl' -> {'name': 'foo', 'version': '1.0', 'build': None, 'tags': [{'interpreter': 'py3', 'abi': 'none', 'platform': 'any'}]}."""
    try:
        name, version, build, tags = _parse_wheel_filename(filename)
        result = {
            "name": str(name),
            "version": str(version),
            "build": None,
            "tags": []
        }
        if build:
            result["build"] = {"number": str(build[0]), "suffix": build[1]}
        for tag in tags:
            result["tags"].append({
                "interpreter": tag.interpreter,
                "abi": tag.abi,
                "platform": tag.platform
            })
        return result
    except InvalidWheelFilename as e:
        raise ValueError(str(e)) from e
