from packaging.ranges import VersionRange


def union_version_ranges(version_range_a: str, version_range_b: str) -> str:
    """Find the union of two version ranges. version_range_a: First version range in PEP 440 format, version_range_b: Second version range in PEP 440 format. Example: union_version_ranges(">=1.0", "<2.0") -> ">=1.0,<2.0"."""
    try:
        range_a = VersionRange(version_range_a)
        range_b = VersionRange(version_range_b)
        result = range_a.union(range_b)
        return str(result)
    except Exception as e:
        raise ValueError(f"Invalid version range: {e}")
